"""CREDITS.md: who drew each holiday icon the profile uses.

Generated by tools/build.py from holidays.toml, in calendar order. Every
icon in use is listed with a link to its Noun Project page, its creator,
the licence it was downloaded under and what was changed.
"""

from __future__ import annotations

from holidays import Holiday

HEADER = (
    "<!-- Generated by tools/build.py from holidays.toml. Edit that, not this file. -->\n\n"
    "# Credits\n\n"
    "The holiday heroes draw an icon behind the clock. Each comes from the\n"
    "[Noun Project](https://thenounproject.com/), downloaded by the\n"
    "maintainer, sanitised by `tools/icons.py` and pinned by hash in\n"
    "`art/icons/`. Every creator is credited here and in the `<desc>` of each\n"
    "hero that shows their icon.\n\n"
    "| Holiday | Icon | Creator | Licence | Changes |\n"
    "| :--- | :--- | :--- | :--- | :--- |\n"
)


def _cell(text: str) -> str:
    return text.replace("|", "\\|")


def used(hs: list[Holiday]) -> list[Holiday]:
    """The holidays that show an icon, in calendar order."""
    return [h for h in hs if h.icon is not None]


def creator_count(hs: list[Holiday]) -> int:
    return len({h.icon["creator"] for h in used(hs) if h.icon})


def markdown(hs: list[Holiday]) -> str:
    rows = []
    for h in used(hs):
        icon = h.icon or {}
        link = f"[{_cell(icon['title'])}]({icon['url']})"
        rows.append(
            f"| {_cell(h.name)} | {link} | {_cell(icon['creator'])} | {icon['licence']} | recoloured and resized |"
        )
    return HEADER + "\n".join(rows) + "\n"
